    "Green Fee-Free Account": {
      "Rho_foreign_ATM_fee": "$0.00",
      "third_party_ATM_fee_rebate": "Not listed; operator fees may still apply",
      "daily_ATM_limit": "$500",
      "monthly_maintenance": "$22.50, waived with a minimum daily balance of $150"
    }
  },
  "travel_tips": [
    "Choose to be charged in the local currency rather than accepting dynamic currency conversion.",
    "Make fewer, larger withdrawals where safe to reduce per-withdrawal operator surcharges.",
    "Check the ATM screen for its surcharge before confirming."
